mapper.select:
SELECT a.account_id AS open_id, u.nick_name AS user_name, u.phone, a.* FROM sys_account a LEFT JOIN sys_user u ON a.user_id = u.user_id
a.del_flag != #{pageDTO.delFlag}
AND ( u.nick_name LIKE CONCAT('%',#{pageDTO.searchValue},'%') OR a.nick_name LIKE CONCAT('%',#{pageDTO.searchValue},'%') )

SELECT *
FROM sys_account a
WHERE a.user_id = #{userId}
  AND a.account_code = #{accountCode}
  AND a.source_flag = #{sourceFlag}
LIMIT 1
